def jml(s):
 s=s.replace('data-diagram="iamLifecycle"','data-diagram="iamLifecycle" data-relationship="illustrative-lifecycle"')
 # Mover is a repeatable event rather than a stage every identity must pass.
 s=s.replace('02 MOVER','MOVER').replace('<h5 class="reading-mob-tier-name">MOVER (ย้ายฝ่าย)</h5>','<h5 class="reading-mob-tier-name" data-optional="true" data-repeatable="true">MOVER (optional / repeatable)</h5>')
 s=s.replace('</div>\n`,','<p class="reading-semantic-note">An identity can leave without a Mover event and can move roles repeatedly. Periodic Access Reviews apply throughout. / ผู้ใช้ย้ายบทบาทได้หลายครั้ง หรือออกจากองค์กรโดยไม่เคยย้ายบทบาท ต้องทบทวนสิทธิ์ตลอดวงจร</p>\n</div>\n`,')
 return s
diagram('iamLifecycle',jml,'Add explicit optional/repeatable Mover context while retaining valid lifecycle and continuous review; do not rewrite already corrected Leaver retention.')
